export type CrmSource = "website" | "manual";

/** One row of public.crm_inquiries as the dashboard sees it. */
export type CrmRecord = {
  id: string;
  full_name: string;
  email: string;
  /** "YYYY-MM-DD": the date of the event, chosen by the customer/admin. */
  event_date: string | null;
  occasion_type: string | null;
  guest_count: number | null;
  event_description: string;
  source: CrmSource;
  phone: string | null;
  event_location: string | null;
  extra: Record<string, string>;
  /** ISO timestamp generated by the database when the record was created. */
  created_at: string;
  updated_at: string;
};

export const PAGE_SIZE = 25;

export type CrmSort = "created_at" | "event_date";

export type CrmListParams = {
  q: string;
  source: "all" | CrmSource;
  sort: CrmSort;
  dir: "asc" | "desc";
  page: number;
};

export type CrmCounts = { total: number; website: number; manual: number };

export type CrmListResult =
  | { ok: true; rows: CrmRecord[]; total: number; counts: CrmCounts; page: number }
  | { ok: false; message: string };

export type CrmFieldName = "full_name" | "email" | "event_date" | "occasion_type" | "guest_count" | "event_description";
export type CrmFieldErrors = Partial<Record<CrmFieldName, string>>;

export type CrmMutationResult =
  | { ok: true; record?: CrmRecord }
  | { ok: false; message: string; fieldErrors?: CrmFieldErrors };
